# verify demo rule: walk inward for upper member (r+1,c-1) when r<c; (r-1,c+1) when r>c; (r+1,c+1) when r==c
def fill2(g):
    g=[row[:] for row in g]; n=len(g)
    for _ in range(n*n):
        if not any(g[r][c]==6 for r in range(n) for c in range(n)): break
        for r in range(n):
            for c in range(n):
                if g[r][c]==6:
                    if g[c][r]!=6: g[r][c]=g[c][r]
                    else:
                        a,b=sorted((r,c))
                        # walk from (a,b) inward: (a+1,b-1) if a<b else (a+1,b+1) if a==b... use a+1,b-1 when a<b
                        aa,bb=a,b
                        while True:
                            if a<b: aa,bb=aa+1,bb-1
                            else: aa,bb=aa+1,bb+1
                            if not(0<=aa<n and 0<=bb<n): break
                            if g[aa][bb]!=6: g[r][c]=g[aa][bb]; break
                        if g[r][c]==6:
                            aa,bb=a,b
                            while True:
                                aa,bb=aa-1,bb-1 if a==b else (aa-1,bb+1)
                                if not(0<=aa<n and 0<=bb<n): break
                                if g[aa][bb]!=6: g[r][c]=g[aa][bb]; break
    return g
