def comps(g):
    n=len(g); seen=set(); out=[]
    for r in range(n):
        for c in range(n):
            if g[r][c]==6 and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<n and 0<=y<n and g[x][y]==6 and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(comp)
    return out
