# orbits under group {id, transpose, flipud, fliplr, ...}
def orbit(r,c):
    pts={(r,c)}
    # apply: (r,c)->(c,r) [transpose], (29-r,c)[flipud], (r,29-c)[fliplr]
    gens=[lambda r,c:(c,r),lambda r,c:(29-r,c),lambda r,c:(r,29-c)]
    changed=True
    while changed:
        changed=False
        for p in list(pts):
            for fn in gens:
                q=fn(*p)
                if q not in pts: pts.add(q); changed=True
    return pts
def solve(g):
    g=[row[:] for row in g]; n=30
    seen=set(); unresolved=[]
    for r in range(n):
        for c in range(n):
            if (r,c) in seen: continue
            orb=orbit(r,c); seen|=orb
            vals=[g[a][b] for a,b in orb]
            nz=[v for v in vals if v!=6]
            if nz:
                for a,b in orb: g[a][b]=nz[0]
            else:
                unresolved.append(orb)
    return g, unresolved
